 bounds,translation=row.split('~',1); start,end=map(int,bounds.split('-')); spans=[dict(line=n,time=raw[n-1][0],text=raw[n-1][1]) for n in range(start,end+1)]
 hanzi=''.join(re.sub(r' \[SOURCE GAP:.*?\]','',s['text']) for s in spans)
 syllables=[x[0] for x in pinyin(hanzi,style=Style.TONE,heteronym=False,errors=lambda x:list(x))]
